        def login_success():
                sucess_dialog = QtWidgets.QMessageBox()
                sucess_dialog.setText('Login Successful!')
                sucess_dialog.exec_()

        def login_database():
           try:
                conn = sqlite3.connect("login.db") # accesses the database
                cur = conn.cursor()

                entered_password_hash = hashlib.sha256(self.PasswordEntry.text().encode()).hexdigest()

                cur.execute("SELECT * FROM login WHERE username =? AND password=?", (self.UsernameEntry.text(), entered_password_hash)) #searches for the username and password entered
                row =cur.fetchall() # finds the example of username and password
                if row !=[]:
                        user_name = row[0][0]
                        login_success()
                        self.window = QtWidgets.QMainWindow()
                        self.ui = Ui_MainScreen()
                        self.ui.setupUi(self.window)
                        self.window.show()
                else:
                      login_error()
                      
           except Exception as e:
                print(f"Error: {e}")
        login_database()

